// Package lru implements a fixed-capacity least-recently-used cache.
//
// Entries live in a slice of nodes linked into an intrusive doubly linked
// list by index, with a map from key to node index. Every operation runs in
// O(1) expected time.
package lru

const nilSlot = -1

type node struct {
	key, value string
	prev, next int32
}

// Cache is a fixed-capacity LRU cache mapping strings to strings.
// The zero value is not usable; create one with New.
type Cache struct {
	capacity int
	index    map[string]int32
	nodes    []node
	head     int32 // most recently used
	tail     int32 // least recently used
	free     int32 // stack of reusable slots, linked through next
}

// New returns an empty cache that holds at most capacity entries.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be at least 1")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32),
		head:     nilSlot,
		tail:     nilSlot,
		free:     nilSlot,
	}
}

// Len reports the number of entries held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	slot, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.nodes[slot].value, true
}

// GetBytes is like Get but takes the key as a byte slice, avoiding an
// allocation for the lookup.
func (c *Cache) GetBytes(key []byte) (string, bool) {
	slot, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.nodes[slot].value, true
}

// Set stores value under key and marks it most recently used, evicting the
// least recently used entry if the cache would exceed its capacity.
func (c *Cache) Set(key, value string) {
	if slot, ok := c.index[key]; ok {
		c.nodes[slot].value = value
		c.moveToFront(slot)
		return
	}
	if len(c.index) >= c.capacity {
		c.evict()
	}
	slot := c.allocate()
	c.nodes[slot].key = key
	c.nodes[slot].value = value
	c.index[key] = slot
	c.pushFront(slot)
}

// SetBytes is like Set but takes byte slices. The slices are copied only
// when needed, so callers may reuse them afterwards.
func (c *Cache) SetBytes(key, value []byte) {
	if slot, ok := c.index[string(key)]; ok {
		c.nodes[slot].value = string(value)
		c.moveToFront(slot)
		return
	}
	c.Set(string(key), string(value))
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	slot, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(slot)
	return true
}

// DeleteBytes is like Delete but takes the key as a byte slice.
func (c *Cache) DeleteBytes(key []byte) bool {
	slot, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.remove(slot)
	return true
}

func (c *Cache) evict() { c.remove(c.tail) }

func (c *Cache) remove(slot int32) {
	delete(c.index, c.nodes[slot].key)
	c.unlink(slot)
	c.release(slot)
}

func (c *Cache) allocate() int32 {
	if c.free != nilSlot {
		slot := c.free
		c.free = c.nodes[slot].next
		return slot
	}
	c.nodes = append(c.nodes, node{})
	return int32(len(c.nodes) - 1)
}

func (c *Cache) release(slot int32) {
	// Drop references so the strings can be collected.
	c.nodes[slot] = node{prev: nilSlot, next: c.free}
	c.free = slot
}

func (c *Cache) pushFront(slot int32) {
	n := &c.nodes[slot]
	n.prev = nilSlot
	n.next = c.head
	if c.head != nilSlot {
		c.nodes[c.head].prev = slot
	} else {
		c.tail = slot
	}
	c.head = slot
}

func (c *Cache) unlink(slot int32) {
	n := &c.nodes[slot]
	if n.prev != nilSlot {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilSlot {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
}

func (c *Cache) moveToFront(slot int32) {
	if slot == c.head {
		return
	}
	c.unlink(slot)
	c.pushFront(slot)
}

package lru

import "testing"

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len = %d, want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q, want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3)
	for i := 0; i < 100; i++ {
		c.Set("x", "1")
		if !c.Delete("x") || c.Delete("x") {
			t.Fatal("unexpected Delete result")
		}
	}
	if c.Len() != 0 || len(c.nodes) != 1 {
		t.Fatalf("Len = %d, nodes = %d", c.Len(), len(c.nodes))
	}
}

// Command app simulates an LRU cache driven by commands read from stdin.
// See SPEC.md for the input format.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"

	"lru-sim/lru"
)

func main() {
	input, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "app: reading stdin:", err)
		os.Exit(1)
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	run(input, w)
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "app: writing stdout:", err)
		os.Exit(1)
	}
}

// run executes the command script in input and writes the results to w.
func run(input []byte, w *bufio.Writer) {
	first, rest, _ := bytes.Cut(input, []byte{'\n'})
	capacity, ok := parseLeadingInt(first)
	if !ok || capacity < 1 {
		return
	}
	cache := lru.New(capacity)

	for len(rest) > 0 {
		var line []byte
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		line = bytes.TrimSuffix(line, []byte{'\r'})
		if len(line) == 0 {
			continue
		}
		cmd, args, hasArgs := bytes.Cut(line, []byte{' '})
		switch string(cmd) {
		case "SET":
			key, value, ok := bytes.Cut(args, []byte{' '})
			if ok {
				cache.SetBytes(key, value)
			}
		case "GET":
			if hasArgs {
				if v, ok := cache.GetBytes(args); ok {
					w.WriteString(v)
				} else {
					w.WriteString("NULL")
				}
				w.WriteByte('\n')
			}
		case "DEL":
			if hasArgs {
				if cache.DeleteBytes(args) {
					w.WriteString("1\n")
				} else {
					w.WriteString("0\n")
				}
			}
		case "SIZE":
			w.Write(strconv.AppendInt(w.AvailableBuffer(), int64(cache.Len()), 10))
			w.WriteByte('\n')
		default:
			// Unknown commands are ignored.
		}
	}
}

// parseLeadingInt parses an optionally signed decimal integer prefix of b,
// after skipping leading whitespace and ignoring any trailing characters.
// Values too large for an int saturate.
func parseLeadingInt(b []byte) (int, bool) {
	i := 0
	for i < len(b) && isSpace(b[i]) {
		i++
	}
	neg := false
	if i < len(b) && (b[i] == '+' || b[i] == '-') {
		neg = b[i] == '-'
		i++
	}
	start := i
	n := 0
	for ; i < len(b) && b[i] >= '0' && b[i] <= '9'; i++ {
		d := int(b[i] - '0')
		if n > (math.MaxInt-d)/10 {
			n = math.MaxInt
		} else {
			n = n*10 + d
		}
	}
	if i == start {
		return 0, false
	}
	if neg {
		n = -n
	}
	return n, true
}

// isSpace reports whether c is whitespace when the input is read as Latin-1.
func isSpace(c byte) bool {
	switch c {
	case ' ', '\t', '\n', '\v', '\f', '\r', 0xA0:
		return true
	}
	return false
}
